const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,overflow=Math.max(0,text.scrollWidth-messageBox.clientWidth+16);messageBox.scrollLeft=0;
if(!reduced){noticeAnimations.push(bar.animate([{boxShadow:'0 0 0 transparent'},{boxShadow:kind==='loss'||kind==='error'?'0 0 12px #e89c9c':'0 0 12px #9cdbb3'},{boxShadow:'0 0 0 transparent'}],{duration:450}));if(overflow>0){hold=Math.min(8000,Math.max(hold,1700+overflow/50*1000));noticeAnimations.push(text.animate([{transform:'translateX(0)',offset:0},{transform:'translateX(0)',offset:.18},{transform:`translateX(-${overflow}px)`,offset:.85},{transform:`translateX(-${overflow}px)`,offset:1}],{duration:hold,fill:'forwards'}));}}
