let tallestView=innerHeight;function keyboardLayout(){tallestView=Math.max(tallestView,innerHeight);const f=document.activeElement,typing=!!f&&f.matches('textarea,input:not([type=checkbox]):not([type=radio]):not([type=range]):not([type=file])')&&!f.closest('dialog');document.body.classList.toggle('keyboardOpen',typing&&innerHeight<tallestView*0.75);}addEventListener('resize',keyboardLayout);document.addEventListener('focusin',keyboardLayout);document.addEventListener('focusout',()=>setTimeout(keyboardLayout,0));
