let apkExporting=false;
function apkExportForm(){
const landingGame=store.active,landingProject=project,validLanding=()=>activeForm?.meta.type==='landing'&&store.active===landingGame&&project===landingProject;const l=project.landing||{};open('메인 화면·APK',`<label>게임 이름<input id="apkTitle" maxlength="100" value="${esc(project.title)}"></label><div id="landingCardWrap"><div id="landingCardPreview"></div></div><div class="row"><button id="landingPick">메인 그림 선택</button><button id="landingDefault" class="quiet">기본 그림 사용</button></div><button id="landingPosition" class="full quiet">그림 위치 조절</button><div class="iconPreviewRow"><button id="iconPosition" aria-label="앱 아이콘 위치 조절"><img id="iconSquare" alt="사각형 아이콘 미리보기"><img id="iconRound" alt="원형 아이콘 미리보기"><span>앱 아이콘 조절</span></button></div><details><summary>아이콘 그림 · 선택</summary><div class="row"><button id="iconPick">별도 그림 선택</button><button id="iconDefault" class="quiet">메인 그림 사용</button></div></details><label>짧은 소개 · 선택<textarea id="landingIntro" rows="1" maxlength="160">${esc(l.intro||'')}</textarea></label><label>제작자 이름 · 선택<input id="landingAuthor" maxlength="80" value="${esc(l.author||'')}"></label><label>크레딧 · 선택<textarea id="landingCredits" rows="3" maxlength="4000" placeholder="그림, 음악, 도움을 준 사람과 출처">${esc(l.credits||'')}</textarea></label><details id="apkMediaSummary"><summary></summary><ul></ul></details><p class="hint">현재 편집본과 그림·소리를 담습니다. 업데이트 APK를 계속 만들려면 에디터 앱 데이터를 유지하세요.</p><div class="formFooter apkFooter"><small id="apkExportMessage" role="status">입력은 자동 저장됩니다.</small><button id="makeGameApk">${apkExporting?'APK 만드는 중…':'게임 APK로 저장'}</button></div>`);
let iconPreviewToken=0;function preview(){mediaSummary();const token=++iconPreviewToken;ImageCompose.icon({...project,title:$('apkTitle')?.value.trim()||project.title}).then(src=>{if(token!==iconPreviewToken||!$('iconSquare'))return;for(const id of ['iconSquare','iconRound']){$(id).hidden=!src;if(src)$(id).src=src;}}).catch(()=>{});GameTitle.preview($('landingCardPreview'),{...project,title:$('apkTitle').value||'게임 이름'},{...project.landing,intro:$('landingIntro').value,author:$('landingAuthor').value,credits:$('landingCredits').value});}
function commit(report=false){if(!$('apkTitle').value.trim())return report?formError('게임 이름을 입력하세요.','apkTitle'):false;project.title=$('apkTitle').value.trim();project.landing||={};Object.assign(project.landing,{intro:$('landingIntro').value,author:$('landingAuthor').value,credits:$('landingCredits').value});persist();return true;}
bindForm({type:'landing',id:'game'},commit,preview);$('landingPick').onclick=()=>{imageCallback=image=>{if(!validLanding())return;project.landing||={};project.landing.image=image;delete project.landing.cover;persist();preview();};$('imageFile').click();};$('landingDefault').onclick=()=>{if(project.landing)delete project.landing.image;persist();preview();};$('landingPosition').onclick=()=>openCrop('cover',preview);$('iconPosition').onclick=()=>openCrop('icon',preview);$('iconPick').onclick=()=>{imageCallback=image=>{if(!validLanding())return;project.landing||={};project.landing.icon={image};persist();preview();};$('imageFile').click();};$('iconDefault').onclick=()=>{if(project.landing)delete project.landing.icon;persist();preview();};$('makeGameApk').disabled=apkExporting;$('makeGameApk').onclick=()=>{if(commit(true))exportGameApk();};exportBusy(apkExporting);preview();
}
// What the APK will carry, so the biggest files can be replaced before exporting.
function mediaSummary(){const box=$('apkMediaSummary');if(!box)return;const items=MediaPack.inventory(project),sum=MediaPack.summary(items),mb=MediaPack.mb;box.hidden=!items.length;if(!items.length)return;box.querySelector('summary').textContent='담을 그림 '+sum.images+'장 · '+mb(sum.imageBytes)+(sum.sounds?', 소리 '+sum.sounds+'개 · '+mb(sum.soundBytes):'');box.querySelector('ul').innerHTML=items.slice(0,5).map(i=>'<li>'+esc(i.label)+' · '+(i.kind==='image'?'그림':'소리')+' '+mb(i.bytes)+'</li>').join('')+(items.length>5?'<li>외 '+(items.length-5)+'개</li>':'')+'<li class="hint">내보낼 때 그림은 WebP로'+(sum.uncompressed?', WAV·FLAC 소리 '+sum.uncompressed+'개는 Opus로':'')+' 줄여 담습니다.</li>';}
function apkMessage(message,error=false){const box=$('apkExportMessage');if(box){box.textContent=message;box.classList.toggle('loss',error);}else tell(message);}
function exportBusy(value){apkExporting=value;if($('makeGameApk'))$('modalBody').querySelectorAll('input,textarea,#landingPick,#landingDefault,#landingPosition,#iconPosition,#iconPick,#iconDefault').forEach(x=>x.disabled=value);for(const id of ['exportApk','makeGameApk'])if($(id)){$(id).disabled=value;$(id).classList.toggle('busy',value);$(id).textContent=value?'APK 만드는 중…':id==='exportApk'?'게임 APK로 내보내기':'게임 APK로 저장';}$('saveStatus')?.classList.toggle('apkBusy',value);}
async function exportGameApk(){
if(apkExporting||creatorBusy||standalone)return;if(window.Android?.creatorInfo){try{C.validate(clone(project));if(C.inspect(project).some(i=>i.level==='error'))return showChecks();const info=JSON.parse(Android.creatorInfo(store.active));if(info.error)throw Error(info.error);if(info.mode==='none'||info.mode==='portable'&&!info.backedUp)return creatorBackupForm(true);}catch(e){return apkMessage(e.message,true);}}exportBusy(true);let started=false;try{const snapshot=clone(project);if(!snapshot.title.trim())throw Error('게임 이름을 입력하세요.');C.validate(snapshot);if(C.inspect(snapshot).some(i=>i.level==='error'))return showChecks();if(!window.Android?.exportGameApk)throw Error('APK 내보내기는 Android 앱에서 사용할 수 있습니다.');if(!await flushEditor())throw Error('편집 내용을 저장하지 못했습니다.');
const g=GameVault.game(snapshot,true);g.id=store.active;const pack=GameVault.create(snapshot,true);pack.games=[g];pack.active=g.id;pack.exportIcon=await ImageCompose.icon(snapshot);let data=GameVault.encode(pack),report='';
// Pictures and sounds go into the APK as separate, smaller files; game.json only names them.
if(Android.stageExportMedia){if(!Android.clearExportMedia())throw Error('다른 파일 저장을 먼저 마쳐 주세요.');const prepared=await MediaPack.prepare(data,{hash:GameDepot.hash,stage:(name,base64)=>Android.stageExportMedia(name,base64),onProgress:(i,n)=>apkMessage('그림·소리를 줄이는 중… '+i+'/'+n)});const file=JSON.parse(prepared.data);file.exportFonts=MediaPack.fonts(snapshot.theme);data=JSON.stringify(file);report=MediaPack.describe(prepared.report);}
if(new TextEncoder().encode(data).length>50000000)throw Error('게임 데이터가 50MB를 넘었습니다. 그림·소리를 줄여 주세요.');if(!Android.exportGameApk(data,g.id,snapshot.title))throw Error('다른 파일 저장을 먼저 마쳐 주세요.');started=true;apkMessage('게임 APK를 만들고 있습니다.'+(report?' '+report+'.':'')+' 생성 후 저장 위치를 고르세요.');}catch(e){apkMessage(e.message,true);}finally{if(!started){if(window.Android?.clearExportMedia)Android.clearExportMedia();exportBusy(false);}}
}
window.onApkExportResult=(ok,message)=>{exportBusy(false);apkMessage(message||(ok?'게임 APK를 저장했습니다.':'APK 내보내기 실패'),!ok&&!/취소/.test(message||''));if(!$('apkExportMessage'))tell(message||(ok?'게임 APK를 저장했습니다.':'APK 내보내기 실패'));};

function themeForm(){
open('화면 테마',`<div id="themeSample" class="themeSample"><div class="themeSampleStatus themeSamplesIcons">${heartIcon}${mentalIcon(3)}<span>체력 · 멘탈</span></div><div class="themeSampleBody"><b class="themeSampleWho">유나</b><p>비가 그치면 함께 걸을까?</p><div class="themeSampleChoices"><span>함께 갈 준비를 한다</span></div></div><div class="themeSampleTools"><span>이전 대화</span><span>배경 보기</span><span class="themeSampleSlider">투명도 ━●━</span></div></div><div class="themeGrid">${GameThemes.catalog.map(t=>`<button class="themePreset" data-theme-pick="${t.id}" aria-pressed="false"><b>${t.name}</b><small>${t.description}</small><span class="themeSwatches" aria-hidden="true">${['surface','accent','choice'].map(k=>`<i style="background:${t.colors[k]}"></i>`).join('')}</span></button>`).join('')}</div><p class="hint">선택하면 자동 저장됩니다. 플레이에 반영 후 새로 시작한 게임에 적용됩니다.</p><button id="themeDone" class="full">완료</button>`);
function update(){const t=GameThemes.get(project.theme);GameThemes.apply($('themeSample'),t.id,project.panelTransparency);$('modalBody').querySelectorAll('[data-theme-pick]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.themePick===t.id)));}
$('modalBody').querySelectorAll('[data-theme-pick]').forEach(b=>b.onclick=()=>{project.theme=b.dataset.themePick;persist();update();});$('themeDone').onclick=closeForm;update();
}

function showChecks(extra=''){
const issues=C.inspect(project);open('이야기 점검',`<p class="hint">연결·입력과 획득 항목의 사용처를 확인합니다. 보유 상태별 모든 경로를 증명하는 검사는 아니므로 조건 분기는 직접 테스트하세요.</p>${extra?`<p class="loss">${esc(extra)}</p>`:''}${issues.length?issues.map((i,n)=>`<button class="issue" data-issue="${n}"><b>${i.level==='error'?'수정 필요':'확인'} · ${esc(project.events.find(e=>e.id===i.event)?.title||'시작 설정')}</b><span>${esc(i.message)}</span></button>`).join(''):'<p>발견된 연결·입력 문제가 없습니다.</p>'}`);
$('modalBody').querySelectorAll('[data-issue]').forEach(b=>b.onclick=()=>{const issue=issues[Number(b.dataset.issue)];$('modal').close();if(issue.event){selected=issue.event;part=issue.choice?'choices':'content';page='story';}else page='inventory';render();const choice=issue.choice&&project.events.find(x=>x.id===issue.event)?.choices.find(c=>c.id===issue.choice);if(choice)choiceForm(choice);else $('editor')?.scrollTo?.({top:0});});
}
$('checkStory').onclick=()=>showChecks();$('testHere').onclick=()=>{try{C.validate(clone(project));if(C.inspect(project).some(i=>i.level==='error'))return showChecks();}catch(e){return showChecks(e.message);}startTest(selected);tell('이 사건부터 테스트합니다. 보유 상태에서 수량을 바꿀 수 있어요.');};
function deleteEvent(e){
if(project.events.length===1)return tell('사건은 하나 이상 있어야 합니다.');
const refs=[];for(const x of project.events)if(x.id!==e.id)for(const c of x.choices){if(c.next===e.id)refs.push({scene:x,c,out:c});if(c.branch?.next===e.id)refs.push({scene:x,c,out:c.branch});}
const remove=()=>{const at=project.events.findIndex(x=>x.id===e.id);project.events=project.events.filter(x=>x.id!==e.id);selected=project.events[Math.max(0,at-1)].id;persist();renderEditor();tell('사건을 삭제했습니다. ↶ 되돌리기로 복구할 수 있어요.');};
if(!refs.length){if(confirm('「'+(e.title||'제목 없음')+'」 사건을 삭제할까요? ↶ 되돌리기로 복구할 수 있어요.'))remove();return;}
open('연결된 사건 삭제',`<p>「${esc(e.title)}」${josa(e.title||'사건','으로')} 연결된 결과가 ${refs.length}개 있어요. 대신 연결할 곳을 정한 뒤 삭제하세요.</p><p class="hint">${refs.slice(0,3).map(r=>esc(r.scene.title)+' → '+esc(r.c.text)).join('<br>')}${refs.length>3?'<br>외 '+(refs.length-3)+'개':''}</p><label>대신 연결할 곳<select id="replacement"><option value="">선택해 주세요</option><option value="sequence">사건 끝 · 다음 스토리</option><option value="random">사건 끝 · 랜덤 인카운터</option><option value="end">이야기 끝 · 엔딩</option>${project.events.filter(x=>x.id!==e.id).map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')}</select></label><button id="confirmDelete" class="full danger" disabled>연결을 바꾸고 삭제</button>`);
$('closeModal').textContent='취소';$('replacement').onchange=()=>$('confirmDelete').disabled=!$('replacement').value;$('confirmDelete').onclick=()=>{for(const r of refs)r.out.next=$('replacement').value;$('modal').close();remove();};
}
$('undoTest').onclick=()=>{if(playing||!testPast.length)return;GameAudio.stopAll();run.restore(testPast.pop());clearEffects();renderTest();if($('stateSheet').open)renderStateSheet();};
$('editCurrent').onclick=()=>{GameAudio.stopAll();selected=run.current;part='content';$('stateSheet').close();page='story';render();};
$('adjustTest').onclick=()=>{
$('stateSheet').close();open('테스트 보유량 설정',`<p class="hint">현재 테스트에만 적용합니다. 이야기의 시작 설정은 바뀌지 않습니다.</p><div class="row"><label>체력<input id="tHp" type="number" min="1" max="${run.p.maxHp}" value="${Math.max(1,run.hp)}"></label><label>멘탈<input id="tMental" type="number" min="1" max="3" value="${Math.max(1,run.mental)}"></label><label>돈<input id="tMoney" type="number" min="0" max="3" value="${run.money}"></label></div>${run.p.definitions.map(d=>`<label>${esc(d.name)} ${d.type==='ability'?'레벨':'수량'}<input data-test-quantity="${d.id}" type="number" min="0" max="999" value="${run.bag[d.id]||0}"></label>`).join('')}<button id="applyTestState" class="full">테스트에 적용</button>`);
$('closeModal').textContent='취소';
$('applyTestState').onclick=()=>{const hp=Number($('tHp').value),mental=Number($('tMental').value),money=Number($('tMoney').value),bag=Object.fromEntries([...$('modalBody').querySelectorAll('[data-test-quantity]')].map(x=>[x.dataset.testQuantity,Number(x.value)]));if(!Number.isInteger(hp)||hp<1||hp>run.p.maxHp||!Number.isInteger(mental)||mental<1||mental>3||!Number.isInteger(money)||money<0||money>3||Object.values(bag).some(n=>!Number.isInteger(n)||n<0||n>999))return formError('수량과 생존 자원의 범위를 확인하세요.');testPast.push(run.snapshot());if(testPast.length>30)testPast.shift();Object.assign(run,{hp,mental,money,bag,lastChange:null,message:'테스트 보유량을 적용했습니다.'});if(run.dead){run.dead=false;run.ended=false;run.deathReason='';}$('modal').close();renderTest();};
};

function quickTest(){
 if(playing||!run)return;if(run.pendingReward)return tell('보상을 고른 뒤 조건을 비교하세요.');const e=run.p.events.find(x=>x.id===run.current);if(!e||run.ended)return tell('진행 중인 장면에서 사용할 수 있어요.');
 const requirements=new Map();for(const c of e.choices){for(const [id,n]of[[c.requires,c.requiresCount??1],[c.branch?.when,c.branch?.count??1],[c.lose,c.loseCount??1],[c.branch?.lose,c.branch?.loseCount??1]])if(id)requirements.set(id,Math.max(requirements.get(id)||0,n));}
 for(const text of [e.text,e.speaker,...e.choices.map(c=>c.text)]){const info=GameVariations.inspect(text,n=>run.textValue(n,e)!==undefined);for(const [n,need]of Object.entries(info.needs)){const d=run.p.definitions.find(d=>d.name===n);if(d)requirements.set(d.id,Math.max(requirements.get(d.id)||0,need));}}
 const all=[...requirements].filter(([id])=>!C.resources[id]);
 open('조건 비교',`<p class="hint">현재 테스트의 보유 상태만 바꿉니다. 사건과 시작 설정은 그대로 유지됩니다.</p><div id="compareConditions"></div><p id="compareLine" class="compareLine"></p><div id="compareResults"></div><button id="compareAllState" class="full quiet">체력·멘탈·돈 / 전체 보유량 설정</button>`);
 function draw(){
 $('compareConditions').innerHTML=all.length?all.map(([id,n])=>`<div class="compareCondition"><b>${esc(run.name(id))}</b><button data-compare-id="${id}" data-value="0" class="${run.value(id)<n?'active':''}">미보유</button><button data-compare-id="${id}" data-value="${n}" class="${run.value(id)>=n?'active':''}">보유</button></div>`).join(''):'<p class="hint">이 사건에는 능력·아이템 조건이 없습니다.</p>';
 $('compareConditions').querySelectorAll('[data-compare-id]').forEach(b=>b.onclick=()=>{testPast.push(run.snapshot());if(testPast.length>30)testPast.shift();run.bag[b.dataset.compareId]=Number(b.dataset.value);run.lastChange=null;clearEffects();renderTest();draw();});
 $('compareLine').textContent=run.say(e.text,e);$('compareResults').innerHTML=e.choices.map(c=>{const out=run.resolved(c),effects=[['hp','체력'],['mental','멘탈'],['money','돈']].filter(([key])=>out[key]).map(([key,label])=>label+' '+(out[key]>0?'+':'')+out[key]);if(c.reward)effects.push('랜덤 보상 '+c.reward.pool.length+'종 중 선택');for(const n of out.effectNotes)effects.push(n.name+' 적용');if(out.gain)effects.push(run.name(out.gain)+' +'+(out.gainCount??1));if(out.lose)effects.push(run.name(out.lose)+' -'+(out.loseCount??1));return `<div class="compareResult"><b>${esc(run.say(c.text,e))}</b><small>${run.blocked(c)?(c.hideLocked?'숨김':'선택 불가'):run.outcome(c)===c.branch?'보유 조건 결과':'기본 결과'} · ${esc(effects.join(' · ')||'변화 없음')}<br>→ ${esc(nextName(out.next))}</small></div>`;}).join('');
 }
 $('compareAllState').onclick=()=>{$('modal').close();$('adjustTest').click();};draw();
}

$('quickTest').onclick=quickTest;
function saveAll(){if(savesBusy)return savesOperation.then(()=>saveAll());if(activeForm){rememberForm();activeForm.commit(false);}return playing?saveProgress():flushEditor();}
window.addEventListener('game-audio-error',e=>tell(e.detail));document.addEventListener('visibilitychange',()=>{if(document.hidden){GameAudio.suspend();clearEffects();finishDialogue();saveAll();}else GameAudio.resume();});window.flushPersist=saveAll;window.appBack=()=>{if($('cropSheet').open){closeCrop();return 'HANDLED'}if($('creditsSheet').open){GameTitle.close();return 'HANDLED'}if($('historySheet').open){closeHistory();return 'HANDLED'}if(artViewing){restoreDialogue();return 'HANDLED'}if($('stateSheet').open){closeStateSheet();return 'HANDLED'}if($('modal').open){closeForm();return 'HANDLED'}if(playing){leavePlay();return 'HANDLED'}if(page==='gameList'){showHome();return 'HANDLED'}if(page==='test'||page==='inventory'){switchPage('story');return 'HANDLED'}if(page==='story'){showHome();return 'HANDLED'}return 'EXIT'};init();

async function deleteGame(){if(apkExporting||creatorBusy)return tell('파일 저장이 끝난 뒤 삭제하세요.');if(!confirm('「'+(project.title||'제목 없는 게임')+'」'+josa(project.title||'게임','과')+' 진행을 삭제할까요? 7일 안에 복구할 수 있습니다.'))return;if(!await flushEditor())return;const before=store.games.slice(),trash=store.trash?.slice(),forms={...store.formDrafts},active=store.active;GameManagement.remove(store,active);try{await GameVault.write(store);}catch(e){store.games=before;store.trash=trash;store.formDrafts=forms;store.active=active;return tell('삭제 내용을 저장하지 못했습니다.');}activeForm=null;$('modal').close();const g=store.games.find(g=>g.id===store.active);project=g?clone(g.draft):null;history=project?new EditorHistory(project):null;selected=project?.events[0]?.id||'';dirty=false;run=null;showList('editor');tell('삭제했습니다. 복구 버튼에서 7일 안에 되돌릴 수 있습니다.');}
function showDeletedGames(){GameManagement.expire(store);open('최근 삭제한 게임',`<p class="hint">삭제한 날부터 7일 동안 그림·소리와 진행까지 복구합니다.</p>${store.trash?.length?store.trash.map(t=>`<button class="eventResult" data-restore-game="${t.game.id}"><span>${esc(t.game.draft.title)}</span><small>복구 · ${Math.max(1,Math.ceil((7*86400000-(Date.now()-t.deletedAt))/86400000))}일 남음</small></button>`).join(''):'<p>복구할 게임이 없습니다.</p>'}`);$('modalBody').querySelectorAll('[data-restore-game]').forEach(b=>b.onclick=async()=>{const before=store.games.slice(),trash=store.trash.slice(),forms={...store.formDrafts},active=store.active;try{const g=GameManagement.restore(store,b.dataset.restoreGame);await GameVault.write(store);$('modal').close();await openGame(g.id);tell('게임과 진행을 복구했습니다.');}catch(e){store.games=before;store.trash=trash;store.formDrafts=forms;store.active=active;tell(e.message);}});GameVault.write(store).then(()=>GameVault.prune()).catch(()=>{});}
function finishSettings(){const owner=store.active;let image=project.finish?.death?.image||'';open('사망 연출',`<p class="hint">비우면 원래 장면과 기본 사망 문구를 사용합니다.</p><label>사망 문구<textarea id="deathText" rows="3" maxlength="1000">${esc(project.finish?.deathText||'')}</textarea></label><img id="deathPreview" class="smallMediaPreview" hidden><div class="row"><button id="deathPick">그림 선택</button><button id="deathClear" class="quiet">그림 제거</button></div><button id="deathDone" class="full">완료</button>`);const preview=()=>{const img=$('deathPreview');img.hidden=!image;if(image)img.src=image;};const commit=()=>{project.finish={deathText:$('deathText').value,death:image?{image}: {}};persist();return true;};bindForm({type:'finish',id:'finish'},commit,preview);$('deathPick').onclick=()=>{imageCallback=v=>{if(activeForm?.meta.type!=='finish'||store.active!==owner)return;image=v;preview();commit();};$('imageFile').click();};$('deathClear').onclick=()=>{image='';preview();commit();};$('deathDone').onclick=closeForm;}

let cropCommit=null;function closeCrop(){if(!$('cropSheet').open)return;cropCommit?.();cropCommit=null;$('cropSheet').close();}
function openCrop(kind,refresh){if(apkExporting)return;const meta=project.landing||{},scene=project.events[0],src=(kind==='icon'?meta.icon?.image:'')||meta.image||C.art(project,scene,'top').image||C.art(project,scene,'bottom').image;if(!src)return tell('먼저 메인 그림을 선택하세요.');const frame=$('cropFrame');frame.className=kind==='cover'?'titleFrame':'iconCropFrame';frame.replaceChildren();GameThemes.apply(frame,project.theme);let target=frame;if(kind==='cover'){GameTitle.preview(frame,project,meta);frame.removeAttribute('data-title-preview');target=frame.querySelector('.titleCover');target.querySelector('img')?.removeAttribute('id');frame.querySelector('.titleCard').classList.add('cropTitleGuide');}else{target=document.createElement('div');target.className='iconCropTarget';frame.append(target);const guide=document.createElement('small');guide.textContent='밝은 칸 안이 아이콘에 보입니다. 기기에 따라 점선 동그라미처럼 잘립니다.';frame.append(guide);}let changed=false;let value=ImageCompose.setting(meta[kind]);ImageCompose.paint(target,src,value);const gestures=ImageCompose.gestures(target,value,v=>{value=v;changed=true;});target.tabIndex=0;target.setAttribute('aria-label','그림 표시 위치 · 방향키로 이동, +와 -로 확대');$('cropSheet').showModal();ImageCompose.paint(target,src,value);cropCommit=()=>{if(changed){project.landing||={};project.landing[kind]={...project.landing[kind],...value};persist();}refresh();};$('cropReset').onclick=()=>gestures.reset();$('cropDone').onclick=closeCrop;}
$('cropSheet').addEventListener('cancel',e=>{e.preventDefault();closeCrop();});

let creatorBusy=false,fileExportCallback=null,latestApkCallback=null;
function creatorMessage(text,error=false){const box=$('creatorMessage');if(box){box.textContent=text;box.classList.toggle('loss',error);if(error&&/암호/.test(text))$('creatorPassword')?.focus();}else tell(text);}
function creatorLock(busy){creatorBusy=busy;if($('creatorAction')){$('creatorAction').disabled=busy;$('modalBody').querySelectorAll('input,button').forEach(x=>x.disabled=busy);}$('closeModal').disabled=busy;}
function creatorBackupForm(first=false){if(creatorBusy||apkExporting)return;if(!window.Android?.backupSigning)return tell('제작자 배포 백업은 Android 앱에서 사용할 수 있습니다.');open(first?'첫 배포 · 제작자 백업':'제작자 백업',`<p class="hint">${first?'처음 배포하기 전에 백업을 한 번 저장하세요. 이후 APK는 암호를 다시 묻지 않고 만듭니다.':'현재 게임과 진행, 배포 서명을 한 파일에 보관합니다.'} 복원할 때 이 파일과 암호가 필요합니다.</p><label>백업 암호<input id="creatorPassword" type="password" minlength="4" maxlength="200" autocomplete="new-password" placeholder="4자 이상"></label><label>암호 확인<input id="creatorConfirm" type="password" maxlength="200" autocomplete="new-password"></label><p id="creatorMessage" class="hint" role="status">이 파일은 제작자 보관용입니다. 플레이어에게는 게임 APK를 보내세요.</p><button id="creatorAction" class="full">${first?'백업 저장 후 APK 만들기':'제작자 백업 저장'}</button>`);const target=store.active;$('creatorAction').onclick=async()=>{const password=$('creatorPassword').value;if(password!==$('creatorConfirm').value)return formError('두 암호가 다릅니다.','creatorConfirm');if(password.length<4)return formError('암호를 4자 이상 입력하세요.','creatorPassword');creatorLock(true);let waiting=false;try{if(!await flushEditor())throw Error('편집 내용을 저장하지 못했습니다.');const signing=JSON.parse(Android.backupSigning(target));if(signing.error)throw Error(signing.error);const game=clone(store.games.find(g=>g.id===target));const payload={format:'event-creator-payload',version:1,gameData:GameVault.encode({format:'event-vault',version:1,active:game.id,games:[game],formDrafts:Object.fromEntries(Object.entries(store.formDrafts||{}).filter(([k])=>k.startsWith(game.id+':')))}),signing};creatorMessage(signing.mode==='legacy'?'기존 배포 서명은 현재 휴대폰에서만 사용할 수 있습니다. 게임·진행과 배포 정보는 암호화해 저장합니다.':'게임과 배포 정보를 암호화하는 중…');const data=await CreatorBackup.encrypt(payload,password);fileExportCallback=async(ok,message)=>{creatorLock(false);if(ok){if($('creatorPassword'))$('creatorPassword').value='';if($('creatorConfirm'))$('creatorConfirm').value='';if(signing.mode==='portable'&&!Android.markCreatorBackup(target))return creatorMessage('백업은 저장했지만 완료 표시를 저장하지 못했습니다. 다시 백업하세요.');creatorMessage('제작자 백업을 저장했습니다. 파일과 암호를 보관하세요.');if(first&&store.active===target){$('modal').close();apkExportForm();await exportGameApk();}}else creatorMessage(message);};Android.exportFile(data,(game.draft.title||'게임').replace(/[\\/:*?"<>|]/g,'_')+'-제작자백업.json','application/json');waiting=true;creatorMessage('백업 파일을 저장할 위치를 선택하세요.');}catch(e){creatorMessage(e.message,true);}finally{if(!waiting)creatorLock(false);}};}
window.onFileExportResult=(ok,message)=>{const callback=fileExportCallback;fileExportCallback=null;if(callback)callback(ok,message);};
function creatorRestoreForm(){if(creatorBusy||apkExporting)return;open('제작자 백업 복원',`<p class="hint">게임·그림·음악·진행을 함께 복원합니다. 새 배포 방식의 백업은 다른 휴대폰에서도 같은 게임의 업데이트 APK를 만들 수 있습니다.</p><button id="creatorPick" class="full">제작자 백업 파일 선택</button><small id="creatorFilename" class="audioFileName"></small><label>백업 암호<input id="creatorPassword" type="password" maxlength="200" autocomplete="current-password"></label><details id="latestApkDetails" hidden><summary>오래된 백업의 배포 버전 확인 · 선택</summary><p class="hint">백업 후 APK를 더 배포했다면 최근 APK를 선택하세요. 앱 ID와 서명을 확인하고 더 높은 버전으로 내보냅니다.</p><button id="latestApkPick" class="full quiet">최근 배포 APK 선택</button><small id="latestApkMessage"></small></details><p id="creatorMessage" class="hint" role="status">백업 파일을 고르고 암호를 입력하세요.</p><button id="creatorAction" class="full" disabled>복원</button>`);let raw='',prepared=null,latest=0;const prepare=async()=>{if(prepared)return prepared;if(!raw)throw Error('제작자 백업 파일을 선택하세요.');const p=await CreatorBackup.decrypt(raw,$('creatorPassword').value);if(p.format!=='event-creator-payload'||p.version!==1||!p.signing)throw Error('제작자 백업 내용 형식');const v=GameVault.decode(p.gameData);if(v.games.length!==1||v.trash?.length)throw Error('게임 백업 구성');const game=v.games[0];if(!['portable','legacy'].includes(p.signing.mode)||!Number.isInteger(p.signing.version)||p.signing.version<0)throw Error('배포 백업 형식');prepared={game,signing:p.signing,formDrafts:Object.fromEntries(Object.entries(v.formDrafts||{}).filter(([k])=>k.startsWith(game.id+':')))};$('latestApkDetails').hidden=!window.Android?.chooseLatestApk;return prepared;};$('creatorPassword').oninput=()=>{prepared=null;latest=0;};$('creatorPick').onclick=()=>$('creatorFile').click();$('creatorFile').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>155000000)return creatorMessage('백업 파일 크기 제한');raw=await f.text();prepared=null;latest=0;$('creatorFilename').textContent=f.name;$('creatorAction').disabled=false;$('latestApkDetails').hidden=!window.Android?.chooseLatestApk;};$('latestApkPick').onclick=async()=>{creatorLock(true);try{const p=await prepare();latestApkCallback=(ok,version,message)=>{creatorLock(false);if(ok)latest=Math.max(latest,version);$('latestApkMessage').textContent=message;};if(!Android.chooseLatestApk(JSON.stringify({package:p.signing.package,fingerprint:p.signing.fingerprint})))throw Error('APK 선택기를 열지 못했습니다.');}catch(e){creatorLock(false);creatorMessage(e.message,true);}};$('creatorAction').onclick=async()=>{creatorLock(true);try{const {game,signing,formDrafts}=await prepare();if(!window.Android?.restoreSigning)throw Error('배포 서명 복원은 Android 앱에서 사용할 수 있습니다.');if(store.games.some(g=>g.id===game.id)&&!confirm('같은 게임이 있습니다. 백업 시점의 내용과 진행으로 복원할까요? 지금 내용은 「복원 전」 사본으로 최근 삭제한 게임에 7일간 보관됩니다.'))return;if(!await flushEditor())throw Error('현재 편집 내용을 저장하지 못했습니다.');const result=JSON.parse(Android.restoreSigning(game.id,JSON.stringify(signing),latest));if(!result.ok)throw Error(result.error||'배포 정보 복원 실패');const before=store.games.slice(),trash=store.trash?.slice(),forms={...store.formDrafts},active=store.active;const current=store.games.find(g=>g.id===game.id);store.games=store.games.filter(g=>g.id!==game.id);if(store.games.length>=100)throw Error('게임은 최대 100개까지 보관할 수 있습니다.');store.trash=(store.trash||[]).filter(t=>t.game.id!==game.id);if(current){const copy=clone(current);copy.id=C.uid();copy.draft.title=(copy.draft.title||'제목 없는 게임')+' (복원 전)';store.trash.push({game:copy,deletedAt:Date.now(),formDrafts:{}});}store.games.push(game);store.formDrafts={...Object.fromEntries(Object.entries(store.formDrafts||{}).filter(([k])=>!k.startsWith(game.id+':'))),...formDrafts};store.active=game.id;try{await GameVault.write(store);}catch(e){store.games=before;store.trash=trash;store.formDrafts=forms;store.active=active;throw e;}if(signing.mode==='portable')Android.markCreatorBackup(game.id);$('creatorPassword').value='';creatorLock(false);$('modal').close();await openGame(game.id);tell(signing.mode==='legacy'?'복원했습니다. 기존 서명은 원래 휴대폰이 필요합니다.':'게임·진행·배포 정보를 복원했습니다.');}catch(e){creatorMessage(e.message,true);}finally{creatorLock(false);}};}
window.onLatestApkResult=(ok,version,message)=>{const callback=latestApkCallback;latestApkCallback=null;callback?.(ok,version,message);};
